import{_ as a,o as i,c as s,a2 as o}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"kiwa v1.13 リリース — Realtime 縦軸 (@kiwa/realtime + @kiwa/perf-harness + dogfood 3 app + 時間軸 mock SSOT)","description":"","frontmatter":{"title":"kiwa v1.13 リリース — Realtime 縦軸 (@kiwa/realtime + @kiwa/perf-harness + dogfood 3 app + 時間軸 mock SSOT)","emoji":"🌱","type":"tech","topics":["oss","testing","supabase","ably","realtime"],"published":false},"headers":[],"relativePath":"announcements/v1.13/zenn-article.md","filePath":"announcements/v1.13/zenn-article.md"}'),r={name:"announcements/v1.13/zenn-article.md"};function t(n,e,c,l,d,p){return i(),s("div",null,[...e[0]||(e[0]=[o(`<h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>kiwa v1.13 milestone (<strong>7/7 GitHub Issues resolved</strong>) を land した。 v1.11 で「release 品質を数値で判断可能にする」 縦軸 (5 軸統一 harness + release gate SSOT + dogfood 3 app + docs 3 pillars) を確立、 v1.12 で「非決定性 (AI-LLM cost / latency / token / accuracy) を吸収」 に伸ばした。 v1.13 は同じ縦軸を <strong>時間軸 (Realtime、 sequence の失敗)</strong> に伸ばす。</p><p><code>@kiwa/realtime</code> v0.1 で Supabase Realtime + Ably + Pusher + Socket.io/SSE の 4 provider を 1 mock engine で統一、 5 semantics (presence / broadcast / postgres_changes / room / reconnect) を SSOT 化し、 dogfood 3 app (chat / cursor / notification) を real vs mock で並べる。 <code>@kiwa/perf-harness</code> v0.1 で 5 target 汎用性能測定 (p50 / p95 / p99 + regression) を 11 軸 release gate の <code>perf.p95Ms</code> 軸に feed。 <code>docs/concepts/realtime-testing.md</code> で時間軸 mock を第一級 concept として言語化する。</p><ul><li>親 Issue ... <a href="https://github.com/cardene777/kiwa/issues/709" target="_blank" rel="noreferrer">#709</a></li><li>7 sub-Issue ... <a href="https://github.com/cardene777/kiwa/issues/707" target="_blank" rel="noreferrer">#707</a> (v1.13-1 perf-harness、 単発 land 済) / <a href="https://github.com/cardene777/kiwa/issues/710" target="_blank" rel="noreferrer">#710</a> - <a href="https://github.com/cardene777/kiwa/issues/715" target="_blank" rel="noreferrer">#715</a></li></ul><h2 id="_1-kiwa-perf-harness-v0-1-—-5-target-汎用-perf-v1-13-1" tabindex="-1">1. <code>@kiwa/perf-harness</code> v0.1 — 5 target 汎用 perf (v1.13-1) <a class="header-anchor" href="#_1-kiwa-perf-harness-v0-1-—-5-target-汎用-perf-v1-13-1" aria-label="Permalink to &quot;1. \`@kiwa/perf-harness\` v0.1 — 5 target 汎用 perf (v1.13-1)&quot;">​</a></h2><p>v1.11 の release gate <code>perf.p95Ms</code> 軸は「1 測定 helper に手を入れれば十分」 な軸だが、 実運用で使うには target 別の helper が必要。 v1.13-1 は 5 target を default で提供する。</p><h3 id="_5-target" tabindex="-1">5 target <a class="header-anchor" href="#_5-target" aria-label="Permalink to &quot;5 target&quot;">​</a></h3><ul><li><code>bench.request</code> — HTTP surface (fetch / axios / undici)</li><li><code>bench.function</code> — pure sync/async function</li><li><code>bench.stream</code> — async iterator / Web Streams</li><li><code>bench.batch</code> — bulk operation (DB insert / worker fanout)</li><li><code>bench.worker</code> — Web Worker / Node Worker RPC</li></ul><p>各 target で <code>p50 / p95 / p99 / mean / min / max</code> を出し、 前回 baseline との回帰を <code>regressionRatio</code> で検知する。</p><h3 id="_11-軸-release-gate-との連携" tabindex="-1">11 軸 release gate との連携 <a class="header-anchor" href="#_11-軸-release-gate-との連携" aria-label="Permalink to &quot;11 軸 release gate との連携&quot;">​</a></h3><p><code>buildPerfReport({ target, samples })</code> が <code>QualityReport</code> を出力、 v1.11 で確立した 11 軸 (v1.12 で 11 に拡張) の <code>perf.p95Ms</code> 軸に落とす。 perf-harness は既存の release gate 判定を壊さない完全 additive。</p><h2 id="_2-kiwa-realtime-v0-1-—-4-provider-統一-mock-v1-13-2" tabindex="-1">2. <code>@kiwa/realtime</code> v0.1 — 4 provider 統一 mock (v1.13-2) <a class="header-anchor" href="#_2-kiwa-realtime-v0-1-—-4-provider-統一-mock-v1-13-2" aria-label="Permalink to &quot;2. \`@kiwa/realtime\` v0.1 — 4 provider 統一 mock (v1.13-2)&quot;">​</a></h2><p>1 mock engine、 4 SDK 別 adapter shape。 5 semantics (presence / broadcast / postgres_changes / room / reconnect) を全 SDK で cover。</p><h3 id="_4-provider-adapter" tabindex="-1">4 provider adapter <a class="header-anchor" href="#_4-provider-adapter" aria-label="Permalink to &quot;4 provider adapter&quot;">​</a></h3><ul><li><code>createSupabaseRealtimeMock</code> — <code>channel.on(&#39;presence&#39; | &#39;broadcast&#39; | &#39;postgres_changes&#39;, filter, handler)</code> + <code>channel.track / untrack / send</code></li><li><code>createAblyMock</code> — <code>channels.get / subscribe / presence.subscribe / history rewind</code></li><li><code>createPusherMock</code> — <code>subscribeChannel / bind / trigger</code> + <code>presence-*</code> channel members</li><li><code>createSocketioMock</code> — <code>io(namespace).join(room).emit / on</code> + <code>io.of(namespace).to(room).emit</code></li></ul><h3 id="なぜ「discrete-synchronous-timeline」-か" tabindex="-1">なぜ「discrete + synchronous timeline」 か <a class="header-anchor" href="#なぜ「discrete-synchronous-timeline」-か" aria-label="Permalink to &quot;なぜ「discrete + synchronous timeline」 か&quot;">​</a></h3><p>real socket は jitter + batching + Nagle micro-delay を内包するため、 test で「channel A の event 3 番目が channel B の event 2 番目より先」 のような ordering assertion を書くと flaky になる。 v1.13 mock は event N が subscribe 後 <code>sum(delay[0..N])</code> ms で必ず fire する discrete timeline を採用、 real socket の観測不能な内部状態 (drop count / reconnect attempt / pending queue) を第一級 metric として公開する。</p><p>fidelity harness は real の trace と mock の trace を「同じ scenario 定義」 で並べて実行、 event 列 / order / timing の drift を計測する。 v1.12 で「意図的 deterministic mock + real drift 実測」 を打ち出したのと同じ思想を時間軸に伸ばした形。</p><h2 id="_3-dogfood-3-app-v1-13-3-4-5" tabindex="-1">3. Dogfood 3 app (v1.13-3 / -4 / -5) <a class="header-anchor" href="#_3-dogfood-3-app-v1-13-3-4-5" aria-label="Permalink to &quot;3. Dogfood 3 app (v1.13-3 / -4 / -5)&quot;">​</a></h2><p>chat / cursor / notification の 3 主要 use case を、 real vs mock の 2 mode で走らせて trace 差分から fidelity を実測。</p><h3 id="_3-app-の役割分担" tabindex="-1">3 app の役割分担 <a class="header-anchor" href="#_3-app-の役割分担" aria-label="Permalink to &quot;3 app の役割分担&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>examples/</span></span>
<span class="line"><span>├── dogfood-supabase-realtime-chat/    # broadcast + presence + typing debounce (Next.js + Supabase Realtime)</span></span>
<span class="line"><span>├── dogfood-ably-collab-cursor/        # shared cursor + 60 fps throttle + history rewind (Next.js + Ably)</span></span>
<span class="line"><span>└── dogfood-socketio-notification/     # per-room push + reconnect + pending replay + backpressure (Express + Socket.io/SSE)</span></span></code></pre></div><p>v1.11 / v1.12 dogfood template と同じ 3 layer 構造。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/</span></span>
<span class="line"><span>├── adapters/</span></span>
<span class="line"><span>│   ├── interface.ts   (provider-neutral trace-recording shape)</span></span>
<span class="line"><span>│   ├── mock.ts        (kiwa mock adapter)</span></span>
<span class="line"><span>│   └── real.ts        (real provider + graceful skip)</span></span>
<span class="line"><span>└── flows/</span></span>
<span class="line"><span>    ├── &lt;domain&gt;-flows.ts</span></span>
<span class="line"><span>    └── fidelity.ts     (trace diff + quality-metrics 呼出)</span></span></code></pre></div><h3 id="実運用検証" tabindex="-1">実運用検証 <a class="header-anchor" href="#実運用検証" aria-label="Permalink to &quot;実運用検証&quot;">​</a></h3><p><code>SUPABASE_URL</code> / <code>SUPABASE_ANON_KEY</code> なしで Supabase Realtime dogfood を走らせると、 real adapter が <code>SUPABASE_ENV_MISSING</code> を返して 4 op (<code>joinRoom</code> / <code>sendMessage</code> / <code>getPresence</code> / <code>sendTyping</code>) 全てで divergence を記録、 mock adapter に不当な parity credit を与えない。 local dev で本番 API key を積まないままの走行でも gate が honest に働くことを実測データで実証。</p><p>realtime provider は AI-LLM 分岐 (<code>@kiwa/ai-</code> prefix) に該当しないため 7 軸 common branch で判定される。 11 軸 gate 全体は unchanged、 realtime 特有の追加 axis はなし。</p><h2 id="_4-docs-補強-v1-13-6" tabindex="-1">4. Docs 補強 (v1.13-6) <a class="header-anchor" href="#_4-docs-補強-v1-13-6" aria-label="Permalink to &quot;4. Docs 補強 (v1.13-6)&quot;">​</a></h2><h3 id="tutorial-3-本-5-セクション統一テンプレ、-v1-11-v1-12-と同構造" tabindex="-1">tutorial 3 本 (5 セクション統一テンプレ、 v1.11 / v1.12 と同構造) <a class="header-anchor" href="#tutorial-3-本-5-セクション統一テンプレ、-v1-11-v1-12-と同構造" aria-label="Permalink to &quot;tutorial 3 本 (5 セクション統一テンプレ、 v1.11 / v1.12 と同構造)&quot;">​</a></h3><ul><li>09: Supabase Realtime chat + presence + typing debounce</li><li>10: Ably shared cursor + 60 fps throttle + history rewind</li><li>11: Socket.io notification + reconnect + pending replay + backpressure</li></ul><h3 id="migration-guide-1-本" tabindex="-1">migration guide 1 本 <a class="header-anchor" href="#migration-guide-1-本" aria-label="Permalink to &quot;migration guide 1 本&quot;">​</a></h3><ul><li>v1.12 → v1.13 (additive-only、 diff 形式、 verification コマンド付、 <code>@kiwa/realtime</code> + <code>@kiwa/perf-harness</code> add 1 行 + realtime provider は 7 軸 common branch を維持)</li></ul><h3 id="concept-doc-1-本" tabindex="-1">concept doc 1 本 <a class="header-anchor" href="#concept-doc-1-本" aria-label="Permalink to &quot;concept doc 1 本&quot;">​</a></h3><ul><li><code>docs/concepts/realtime-testing.md</code> — 時間軸 mock SSOT</li></ul><p><code>docs/concepts/realtime-testing.md</code> は v1.13 の思想の芯を言語化する doc。 「realtime provider は server push + client offline + timed order + buffer overflow の 4 経路で scalar test を破る」 「v1.11 + v1.12 の 11 scalar 軸では presence sync 中の event 順序逆転 / offline 中の silent drop / room 間 cross-leak / pending queue flush 失敗の 5 種を捕まえられない」 「解は mock timeline を discrete + synchronous にして sequence を丸ごと観測 + real drift を per-axis (order / timing / drop / reconnect / backpressure) に落とす」 「同じ report を 7 軸 common branch (<code>isAiLlmProvider</code> = false) に落として既存 gate を壊さない」 の 5 段構造。</p><h2 id="_5-vitepress-publish-v1-13-7" tabindex="-1">5. VitePress publish (v1.13-7) <a class="header-anchor" href="#_5-vitepress-publish-v1-13-7" aria-label="Permalink to &quot;5. VitePress publish (v1.13-7)&quot;">​</a></h2><p>v1.11-6 で land した VitePress skeleton (<code>docs/.vitepress/config.mts</code>) は unchanged。 sidebar に新 tutorial 3 本 + concept doc 1 本 + migration v1.12→v1.13 を追記するのみ。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># generate → build → publish の 3 step (v1.11 / v1.12 と同じ)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /docs-generate</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # typedoc + cargo doc + forge doc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # VitePress build → docs/.vitepress/dist/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /docs-publish-kiwa</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # gh-pages branch push</span></span></code></pre></div><p>Playwright docs E2E (<code>tests/docs-site-e2e/</code>) は既存 canonical + v1.12 spec に加えて tutorial 09/10/11 + concept + migration v1.12→v1.13 の 5 spec を追加、 <code>pnpm test:docs-e2e</code> script を新設。 build 後の verification に組み込み。 CI 全面禁止規約 (<code>rules/git-workflow.md</code>) 下で GitHub Actions 一切使わず、 <code>gh-pages</code> branch push だけで <code>https://cardene777.github.io/kiwa/</code> を更新。</p><h2 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h2><p>v1.12 user は zero-migration。 既存 test file はそのまま動く。 v1.13 追加は全て opt-in、 realtime provider を使わない限り <code>@kiwa/realtime</code> は不要、 perf 測定を使わない限り <code>@kiwa/perf-harness</code> は不要。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa/realtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa/perf-harness</span></span></code></pre></div><p>release gate は v1.13 で軸追加なし、 realtime provider は 7 軸 common branch を維持。 詳細 ... <a href="https://github.com/cardene777/kiwa/blob/main/docs/migrations/v1.12-to-v1.13.md" target="_blank" rel="noreferrer">v1.12 → v1.13 migration guide</a>。</p><h2 id="v1-14-候補" tabindex="-1">v1.14+ 候補 <a class="header-anchor" href="#v1-14-候補" aria-label="Permalink to &quot;v1.14+ 候補&quot;">​</a></h2><p>v1.11 milestone parent (#680) で列挙した候補のうち v1.12 / v1.13 で採用しなかったもの + v1.12 announcement で追加した AI-LLM 深化候補。</p><ul><li>Storybook integration (component test 隙間、 v2.0 pull-forward 候補)</li><li>Dragonfly (2025 新興 Redis 互換 cache、 eco system 熟成待ち)</li><li>Reth (Rust Ethereum execution client、 dApp test 需要が育つ)</li><li>Go Iris + Chi (framework 縦深化続き)</li><li>Payment 系 (Stripe / Paddle / Lemon Squeezy webhook mock)</li><li>Search 系 (Meilisearch / Algolia / Typesense)</li><li>Observability 深堀り (OpenTelemetry / Datadog / Sentry mock)</li><li>AI-LLM 深化 (multimodal vision / audio + MCP tool + agent orchestration)</li></ul><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>v1.13 親 Issue ... <a href="https://github.com/cardene777/kiwa/issues/709" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/issues/709</a></li><li>v1.12 milestone 完遂 (11 軸 release gate + AI-LLM 4 SDK 統一 mock の source of truth)</li><li>@kiwa/realtime ... <code>packages/realtime/</code></li><li>@kiwa/perf-harness ... <code>packages/perf-harness/</code></li><li>dogfood 3 app ... <code>examples/dogfood-{supabase-realtime-chat,ably-collab-cursor,socketio-notification}/</code></li><li>4 provider 選定理由 ... Supabase Realtime + Ably = enterprise 2 大 provider、 Pusher = SaaS 標準、 Socket.io/SSE = 直呼び 2 種で自前実装 cover、 4 provider で realtime SaaS 実装の大半を cover</li><li>5 semantics 選定理由 ... presence (誰がいるか) / broadcast (即時全 client 配信) / postgres_changes (DB 同期) / room (namespace 分離) / reconnect (backpressure + retry)、 5 つで realtime の mock 難所を網羅</li><li>時間軸 mock SSOT ... <code>docs/concepts/realtime-testing.md</code></li></ul>`,48)])])}const m=a(r,[["render",t]]);export{u as __pageData,m as default};
